export function getSpeciesByDex(dex: number): PokemonSpecies | null {
  return POKEMON_SPECIES[dex - 1] ?? null;
}

export function findSpeciesByName(query: string): PokemonSpecies[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return POKEMON_SPECIES.filter((p) =>
    p.name.toLowerCase().includes(q) || p.slug.includes(q),
  );
}
